mapper.select:
select
fa.file_name as afAnnexName,
af.*,
mn.*
from  Archive_Borrow mn
left join  Archive_File af on af.Af_Id=mn.Af_Id
left join  SYS_FileAnnex fa on af.Af_Annex_Id=fa.file_id

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Ab_Create_Uname like concat('%',#{params.abCreateUname},'%')
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Ab_Create_Time DESC
    

limit #{params.start},#{params.size}

select count(1) from Archive_Borrow mn left join Archive_File af on af.Af_Id=mn.Af_Id left join SYS_FileAnnex fa on af.Af_Annex_Id=fa.file_id
and mn.Te_Id = #{params.teId}
and mn.Ab_Create_Uname like concat('%',#{params.abCreateUname},'%')
